<?php require '../config/database.php';require '../config/auth.php';require_role('student');$q=$pdo->prepare('SELECT * FROM marks WHERE student_id=? ORDER BY semester,id');$q->execute([$_SESSION['student_id']]);$rows=$q->fetchAll();$g=[];foreach($rows as $r)$g[$r['semester']][]=$r;$page_title='My Marks';require '../includes/header.php';?><h1>My Marks</h1><p class="muted">Semester-wise marks.</p><?php foreach($g as $sem=>$items):?><div class="card" style="margin:15px 0"><div class="title">Semester <?=$sem?></div><table><tr><th>Subject</th><th>Marks</th><th>Result</th></tr><?php foreach($items as $r):?><tr><td><?=htmlspecialchars($r['subject'])?></td><td><?=$r['marks']?></td><td><?=$r['marks']>=40?'Pass':'Fail'?></td></tr><?php endforeach;?></table></div><?php endforeach;?><?php require '../includes/footer.php';?>
